#!/bin/sh
set -eu

# shellcheck source=SCRIPTDIR/lib.sh
. "$(dirname -- "$0")/lib.sh"

read_tool_call
FILE_PATH=$(input_field '.tool_input.file_path // .tool_input.filePath')

if [ -z "$FILE_PATH" ]; then
  exit 0
fi

case "$FILE_PATH" in
*/README.md)
  # Only block if a sibling action.yml exists (meaning this README is auto-generated)
  DIR=$(dirname "$FILE_PATH")
  if [ -f "$DIR/action.yml" ] || [ -f "$DIR/action.yaml" ]; then
    deny 'Action READMEs are auto-generated by gh-action-readme. Run make docs instead of editing directly.'
  fi
  ;;
esac
